struct Node { int value; Node* next; };
std::atomic<Node*> head;

void pop() {
    while (true) {
        Node* old_head = head.load();
        if (!old_head) return;
        // 假設此處發生 Context Switch，且 old_head 被釋放並重新分配 (Assume Context Switch happens here, old_head is freed and reallocated)
        if (head.compare_exchange_strong(old_head, old_head->next)) {
            delete old_head;
            return;
        }
    }
}

